// Modifying records
  type record R2
  {
     integer num
     charstring str
  }
  template R2 m_base := { num := 0, @fuzzy str := testcasename(); }
  template R2 m_modifiedR modifies m_base := { num := 5 } // m_modifiedR.str is still fuzzy
  template R2 m_modifiedR2 modifies m_base := { str := "foobar" } // m_modifiedR2.str is not fuzzy
  template R2 m_modifiedR3 modifies m_base := 
  { str := m_base.str & "_used" } // m_base.str is used in an expression in non-fuzzy assignment
                // so the right hand side of m_base.str is evaluated just once
  template R2 m_modifiedR4 modifies m_base := 
  { @fuzzy str := m_base.str & "_used" } // here, m_base.str would only be evaluated 
                   // whenever m_modifiedR4.str is evaluated 
                   // (fuzzy field assignment overridden by new fuzzy assignment)

